    .hidden { display: none; }
  </style>
</head>
<body>

<div class="box">

  <!-- LOGIN -->
  <div id="loginBox">
    <h2>Entrar</h2>
    <input type="email" id="loginEmail" placeholder="Email">
    <input type="password" id="loginSenha" placeholder="Senha">
    <button onclick="login()">Entrar</button>

    <div class="link" onclick="mostrarCadastro()">Criar conta</div>
  </div>

  <!-- CADASTRO -->
  <div id="cadastroBox" class="hidden">
    <h2>Criar Conta</h2>
    <input type="email" id="cadEmail" placeholder="Email">
    <input type="password" id="cadSenha" placeholder="Senha">
    <button onclick="cadastrar()">Cadastrar</button>

    <div class="link" onclick="mostrarLogin()">Voltar ao login</div>
  </div>

</div>

<script>
  const ADMIN_EMAIL = "limadan389@gmail.com";
  const ADMIN_SENHA = "147025";

  function mostrarCadastro() {
    document.getElementById("loginBox").classList.add("hidden");
    document.getElementById("cadastroBox").classList.remove("hidden");
  }

  function mostrarLogin() {
    document.getElementById("cadastroBox").classList.add("hidden");
    document.getElementById("loginBox").classList.remove("hidden");
  }

  function cadastrar() {
    const email = document.getElementById("cadEmail").value;
    const senha = document.getElementById("cadSenha").value;

    if (!email || !senha) {
      alert("Preencha email e senha!");
      return;
    }

    if (localStorage.getItem("user_" + email)) {
      alert("Esse email já está cadastrado!");
      return;
    }

    localStorage.setItem("user_" + email, senha);
    alert("Conta criada com sucesso!");
    mostrarLogin();
  }

  function login() {
    const email = document.getElementById("loginEmail").value;
    const senha = document.getElementById("loginSenha").value;

    if (email === ADMIN_EMAIL && senha === ADMIN_SENHA) {
      alert("Bem-vindo, Administrador!");
      window.location.href = "admin.html";
      return;
    }

    const senhaSalva = localStorage.getItem("user_" + email);

    if (senhaSalva === senha) {
      alert("Login realizado!");
      window.location.href = "dashboard.html";
    } else {
      alert("Email ou senha incorretos!");
    }
  }
</script>

</body>
</html>

